#![no_std]
// Allow warnings commonly generated by bindgen's FFI structures
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(unused)]
// bindgen emits libm's M_PI/M_E/... as literal f64s, not the std::f64::consts equivalents
#![allow(clippy::approx_constant)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
